package com.staging.sg.fraud.gateway.config;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.security.authorization.AuthorizationDecision;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.core.OAuth2TokenValidator;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class GatewaySecurityConfig{
 @Bean SecurityFilterChain chain(HttpSecurity http,@Value("${fraud-gateway.security.audience}")String audience)throws Exception{http.csrf(c->c.disable()).authorizeHttpRequests(r->r.requestMatchers("/api/fraud-gateway/v1/health").permitAll().anyRequest().access((a,c)->{var x=a.get();return new AuthorizationDecision(x instanceof JwtAuthenticationToken jwt&&jwt.getToken().getAudience().contains(audience));})).oauth2ResourceServer(o->o.jwt(j->{}));return http.build();}
 @Bean JwtDecoder decoder(@Value("${fraud-gateway.security.issuer-uri}")String issuer,@Value("${fraud-gateway.security.jwk-set-uri}")String jwks){NimbusJwtDecoder d=NimbusJwtDecoder.withJwkSetUri(jwks).build();OAuth2TokenValidator<Jwt> v=JwtValidators.createDefaultWithIssuer(issuer);d.setJwtValidator(v);return d;}
}
